      '1911 年 10 月 10 日晚，武昌新军工八营的一声枪响，本该是一场注定失败的起义——名册已被搜走，领导人或死或逃，群龙无首。然而两个月内十余省相继独立，次年 2 月 12 日清帝退位：从秦始皇到溥仪，两千一百三十二年的帝制，在一声枪响后不到四个月里轰然落幕。',
