          '按当时的战争惯例，破城后劫掠三日：避入圣索菲亚的平民被成群掳走，数以万计的市民沦为奴隶（一说约三万），图书与圣物或焚或散。拜占庭一千年的字画、圣像与典籍，一半毁于炮火，一半散于战场——一座图书馆规模的城市之死。',
