          '帝国的余脉随后逐一熄灭：特拉比松 1461 年陷落，伯罗奔尼撒紧随其后。另一条幽灵般的继承线却在北方展开：1472 年，莫斯科大公伊凡三世迎娶末代皇室的侄女索菲娅，双头鹰徽记北迁——「第三罗马」的说法从此挂在了莫斯科的城门上。',
