          '更深的变化在地图上：伊斯兰与基督教世界的分界线，从此大体固定在巴尔干，一钉就是五百年。同时，一个新帝国借旧帝国的尸骨站了起来——奥斯曼此后两个世纪横跨三洲，它的黄金时代，恰恰从这座城市的陷落开始计时。',
