          '战争的种子埋在上一场战争的和平里：《凡尔赛条约》的巨额赔款与「战争罪责条款」让德国举国憋屈，1923 年的恶性通胀把中产存款变成废纸，1929 年起的大萧条又把失业人口推到六百万——魏玛共和国在通胀与失业的双重打击下中风瘫痪。1933 年，希特勒经由合法选举上台：民主体制亲手选出了自己的掘墓人，这一课后来被反复重修。',
          '绥靖让火药仓满了仓：1938 年慕尼黑会议把苏台德地区拱手让给希特勒，张伯伦挥着协定宣布带回「一代人的和平」；不到半年，捷克斯洛伐克全境被吞。1939 年 8 月，苏德签署互不侵犯条约，密约里夹着瓜分波兰的分界线——挡路的最后一块石头，被两个对手合力搬开。',
          '亚洲线的引信点得更早：日本 1931 年侵占中国东北，1937 年卢沟桥事变全面侵华，同年末的南京大屠杀震动世界。第二次世界大战其实有两个起点——1937 年的亚洲与 1939 年的欧洲，直到 1941 年 12 月珍珠港的爆炸声，才把它们拧成一场真正的世界大战。',
