          '技术分岔延续至今：图灵的解码机催生现代计算机，V-2 火箭的技术谱系通向登月，核物理分裂出能源与医学的同位素应用，雷达与青霉素早已日常化——二战是现代科技的助产士，我们至今没有断奶。今天每一部智能手机里，都有 1940 年代那场战争的军费。',
          '二战留给人类的不只是废墟与条约，而是一条底线共识——再也不能这样打。八十年来大国之间再无直接热战，但战争换了形态从未消失；这条底线没有自动续期，它靠每一代人的记忆续费。记忆一旦免费，底线就会过期——这是 1945 年留给所有后来者的、唯一的租约条款。',
