          '当然账要两面记：否决权让安理会在大国议题上长期瘫痪，敏感议案一次次被一票否决；1991 年苏联解体后的单极时刻与今天的多极拉扯，都在考验 1945 年的设计是否还转得动。宪章序言那句话仍刻在纽约总部的墙上——它不是成就，是未完成的任务。',
