    summary: '殖民体系崩塌的开端：一场独立，两条国界，千万人的迁徙。',
    paragraphs: [
      '1947 年 8 月 14 日午夜，制宪会议大厅里，尼赫鲁说出那句准备了一生的开场白：多年前我们已与命运缔约，此刻正是履行誓约的时候。大厅外，德里在庆祝，卡拉奇也在庆祝；而在旁遮普与孟加拉，一列列火车正在国界两侧对开——有的车厢里装的不是旅客，是相互屠杀后的尸体。同一晚，一个国家诞生，一个次大陆被切开——史上最大规模的权力移交与最惨烈的强制迁徙，发生在同一个月。',
    ],
    sections: [
      {
        heading: '背景火药桶：两百年殖民与「分而治之」',
        paragraphs: [
          '背景要拉回 1857 年大起义：失败之后英国王室直接接管印度，此后近一个世纪，铁路、电报与英语官僚体系把次大陆缝成一体，也把两亿多人口压在殖民经济之下。国大党（1885）与穆斯林联盟（1906）先后成立，最初还坐在同一张谈判桌前；1919 年阿姆利则惨案——英军向集会人群开枪、死伤数百——之后，合作彻底变了味。',
          '裂痕被殖民者与政客共同凿深：选举以宗教社群为单元，真纳与国大党的互疑步步加深，1940 年穆斯林联盟通过「巴基斯坦决议」——穆斯林占多数的西北与东部应当自成国家。二战把进程推到终局：英国打空了国库，1945—46 年选举中穆斯林联盟横扫穆斯林选区，1946 年加尔各答的大屠杀让所有人看清——再谈「统一的印度」，街上已经没人听了。',
        ],
      },
      {
        heading: '经过与转折：蒙巴顿的两个月',
        paragraphs: [
          '末任总督蒙巴顿 1947 年 3 月上任，原定 1948 年 6 月移交权力；他上任两个月就把日期提前到当年 8 月——理由是再拖必乱。边界划分交给从未到过印度的伦敦律师拉德克利夫：用地图与人口普查数字，五周内在旁遮普与孟加拉各划出一条线。',
          '转折的残酷在于：线划在村庄中间、水井之间、亲戚之间。边界公布日期在独立之后——许多人 8 月 15 日刚庆祝完国庆，才发现自己成了另一国的国民。甘地拒绝参加庆典，当天在加尔各答绝食，为的是阻止这座城重演旁遮普的屠杀。关于边界线还有一个细节流传很广：拉德克利夫事后烧掉了全部底稿，拒绝再谈那条线；他 8 月中旬离印，此后终身未再踏上这片土地——他留下的地图，成了两国地图上的第一道伤疤。',
        ],
      },
      {
        heading: '代价：史上最大的强制迁徙',
        paragraphs: [
          '分治引发约 1400 万至 1800 万人的双向大迁徙，是有记录以来规模最大的人口流动。旁遮普的屠杀在最疯狂的一个月里夺走约 20 万至 100 万条生命（估计区间悬殊，两国官方统计至今各执一词），数万名女性遭绑架或强暴——两边的统计几乎对称，仇恨不需要翻译。',
          '甘地为平息加尔各答的仇杀绝食至几乎丧命，1948 年 1 月被一名印度教极端分子刺杀——独立之父死在独立的第一个冬天。真纳同年死于肺结核，没来得及给新国家立好规矩。两个国家的开国一代，都被分治的账单压垮了健康。',
        ],
      },
      {
        heading: '直接后果与长程影响：三条国界与两个核国家',
        paragraphs: [
          '分治的直接后果是三次印巴战争（1947、1965、1971）与克什米尔的悬置——那条拉德克利夫线至今是世上军事化程度最高的边界之一，交火与对峙年年发生；1971 年东巴基斯坦再分出孟加拉国，「两个民族」的理论自己也开始分裂。',
          '长程影响更深远：印巴先后拥核，成为世界上唯一彼此交过火的双核邻国，南亚的发展预算被军备长期虹吸；而分治的幽灵照进了别处——它成了 20 世纪一切「宗教建国」方案的参照样本，从爱尔兰到中东都能听见它的回声。黎明与流血同至，这句话从此写在南亚每一本历史书的开头。',
        ],
      },
    ],
    quote: '多年前我们已与命运缔约，此刻正是履行誓约的时候。',
