          '工艺的关键是组织而非奇迹：本地石灰岩垒核心，阿斯旺的花岗岩走水路，图拉的细白石灰岩做外壳；南北方位靠观星测定。建造方法学界仍在争论（直坡道、螺旋坡道、内坡道诸说并存），但按工程估算，二十年里平均每几分钟就要落位一块巨石——工期几乎无法再压缩——这可能是人类历史上第一个需要「项目管理」的工程。',
