          '胡夫本人的身后命运更讽刺：后世文献把他写成暴君，甚至传他要让女儿卖身筹措工钱（希罗多德记下的传闻）；中世纪以来，金字塔的围石被拆去建开罗的建筑，外壳的白色石灰岩被剥得只剩塔顶一段。国王想永生，国家和后人都不答应。',
