          '粘合剂有三样：共同的神话——赫拉克勒斯或珀罗普斯开创赛会；共同的历法——四年一届的奥林匹克周期；以及「神圣休战」——赛会期间武器不得进入伊利斯境内，往来运动员与观众受宙斯保护。在城邦互杀成风的年代，这是全希腊唯一的停火协议，也是「用规则替代武力」最早的公共实验。',
