          '亚历山大图书馆成了「知识之殇」的永久隐喻：从 2002 年重建开放的亚历山大图书馆，到敦煌藏经洞的对比，人们反复用它提问——文明的记忆银行需要什么样的守护人？托勒密王朝的答案是预算与野心；历史给出的答案是：两者缺一，书就会死——这一课，两千年后的图书馆仍在重修：书会老，守护不能停。',
