          '但这场远征的落点耐人寻味：朱罗人没有留驻一兵一卒，没有设总督府，打完就走。三佛齐未亡，只是海上帝国的垄断被砸开缺口；据载此后两国还有再度交手。这是一种「惩罚式远征」——目的不是占领，而是重新定价：过路费该收多少，从此要问过南印度。1077 年，注辇使团再次入宋，向宋廷进献珍珠与香药，海上商路照旧运转。远征的震动散去后，贸易的账目比战争的胜负更有韧性——海峡的税照收，印度洋的船照开，只是定价权多了一个变量。',
