          '松动从 1977 年就开始：恢复高考，五百七十万人报考、约二十七万人录取，知识与考试重新获得尊严；1978 年 5 月，《实践是检验真理的唯一标准》引发全国大讨论，为政策转向扫清意识形态障碍。12 月的十一届三中全会，正式确立以经济建设为中心、实行改革开放——一场不换旗换路的转型由此启动。',
