          '1991 年 8 月，第一个网站 info.cern.ch 对外开放，内容包括「万维网是什么」以及一份浏览器列表——那张列表本身，就是人类第一次把说明书放在自己家门口。1993 年，CERN 的同事开发了第一款图形浏览器，网页第一次能显示图片，普通人的兴趣瞬间被点燃。',
