          '九十年代末，网站从几百个膨胀到千万个，dot-com 泡沫吹起又破裂——泡沫带走了资金，留下了光缆、服务器与用户习惯。2004 年前后的 Web 2.0 把「发布权」交给普通人：博客、维基、社交网络，内容从机构的输出变成亿万人的日常书写。',
