          '前 490 年，波斯统帅达提斯率舰队横渡爱琴海，先毁厄律特里亚，再登陆阿提卡的马拉松湾。海岸平原能泊船、能列阵，也离雅典仅四十公里——波斯人挑这里登陆，本身就是把战场摆到了雅典家门口。',
          '此时的波斯是横跨三洲的巨兽，雅典立国不过百余年、民主制刚落地几十年。城邦人口约三十万，能披甲上阵的公民兵只占一成——这是一场蚂蚁对巨象的开局。',
