          '利奥波德早有布局。1876 年他召集地理学家开会，宣称向「文明尚未抵达的大陆」传播文明是配得上这个进步世纪的事业——话术是文明，标的是整块大陆。以「国际非洲协会」为门面，他悄悄把刚果盆地变成了个人猎场。',
          '葡萄牙翻出四百年前的教皇文书主张河口主权，英葡条约一签，法国人布拉柴又在北岸插旗。几个欧洲国家的橡皮图章眼看要在非洲顶出火——俾斯麦抓住机会发出请柬：与其在丛林里擦枪走火，不如到柏林把桌子上的规矩定好。',
