          '抵抗同样被碾碎：1897 年英军远征贝宁，王宫洗劫一空，数千件青铜器流散进欧美博物馆；同年阿善提、之后马塔贝莱兰相继陷落。柏林会议的第 34 条催生的，是整个大陆的文物与人口的强制迁移。',
