          '刚果盆地此后一个多世纪的动荡——从殖民榨取到蒙博托的盗国，到大湖区战争——都能在 1884 年那个私人领地里找到起点。经济学家说的「资源诅咒」，在刚果不是比喻，是制度遗产。',
