          '人文主义还炼出一门狠手艺：文献校勘。1440年，瓦拉用语言学的办法证明《君士坦丁赠礼》是几百年前的伪造——教皇世俗权力的法理地基被一纸文书掏空。用古人的文本质疑今人的权力，这个动作成了此后现代学术的模板；1543年哥白尼出版《天体运行论》，科学的引线已经点上。',
