          '约翰签完字转身就翻脸：他说服教皇宣布宪章无效，雇佣兵开进北方，内战爆发。转机荒诞地到来——1216年约翰病死，九岁的亨利三世继位，摄政团为稳住局面重颁宪章。一份失败的停战书，靠着一任任君主「不得不再签一次」，活了下来。',
