          '华尔街的金融工程把这场狂欢标准化：银行向还不起的人发放「次级贷款」——无收入、无工作、无资产者也能签约，反正房子在涨；再把成千上万笔房贷打包成证券（MBS），层层重组为担保债务凭证（CDO），评级机构给其中大部分盖上 AAA 的章——与美国国债同级。想更保险？还有信用违约互换（CDS）：像保单一样给债券买保险，卖保险的 AIG 却没有留足赔付准备金。',
