          '经济的账单同样巨大：2020 年全球 GDP 萎缩约百分之三，是大萧条以来最深衰退；供应链断裂与超发货币共同点燃 2021 至 2022 年的全球通胀，美国 CPI 一度冲上 9.1%。全球约十六亿学生一度停课，人类历史上最大规模的远程教学实验仓促上线——也仓促收场。',
