          '它留给世界的核心公式同样清晰：在一个高度互联的星球上，病毒传播的速度等于全球化的速度，而人类协调的速度远低于此。这三年的全部悲剧与进步，都写在这道差值里——史上最快的疫苗，配上史上最慢的共识。',
