          '武王继位后步步进逼：先在孟津会盟观兵，八百诸侯不期而会，他按兵不动——时机未熟。等帝辛的主力陷在东南、朝歌空虚，历史的窗口打开了。这一退一进之间，商周的胜负其实已经写好。',
