          '战场上的关键一幕是阵前倒戈。据载帝辛把战俘与奴隶临时武装起来顶在阵前，这些人对商毫无忠诚，周军一冲即溃即反，反过头为周军开路。《史记》记商军「七十万」众，学者多认为有夸饰，但倒戈这一幕在多处史料中互证——牧野之战的军事史意义恰在于此：决定战役的是人心，不是人数。',
          '一日溃败，帝辛逃回朝歌，登上鹿台，穿上宝玉衣自焚而死。次日武王入城，斩其头悬于白旗。商立国约五百五十年，终结在一场不到一天的战役里。1976 年陕西出土的利簋，铭文记录「武王征商，唯甲子朝」——战役的具体日期「甲子日」，被一件铜器定格了三千年。',
