          '周公给出的答案是制度。其一，大规模分封：「封建亲戚，以藩屏周」，七十一个封国（同姓五十三国）如钉子般钉在要害——鲁、齐、燕、卫、晋各控一方，姬姓血脉与异姓功臣织成统治网络。其二，宗法制与嫡长子继承，让权力交接有章可循。其三，井田与礼乐：一套靠礼仪、音乐、等级秩序而非恐怖维持的统治技术，「制礼作乐」由此成为中华文明的关键词。',
