          '「中国」二字也诞生于这个时代。1963 年宝鸡出土的何尊，铭文一百二十二字记录成王营建洛邑的诰辞：「余其宅兹中国」——居住在这天下之中。「中国」最初的含义是地理与礼制意义上的中央之国，此后三千年，这个词长成了所有中国人共同的名字。本文配图正是何尊。',
