          '温泉关是必经隘口。利奥尼达王率三百斯巴达卫士加约七千盟军，凭地形血战三天；叛徒带波斯人走山间小径抄后路，隘口注定失守。利奥尼达遣散大部分盟军，与斯巴达人及忒斯庇亚人死战到底——用一场注定的覆灭，为希腊争取集结时间，也为希腊世界立起道德丰碑。',
          '陆上失守，雅典人把老幼迁往萨拉米斯岛，交出城市听任焚毁。德尔斐神谕说雅典只能靠「木墙」，统帅地米斯托克利断言木墙就是战船，并设诈把波斯舰队诱入萨拉米斯狭窄海峡——船多反而施展不开。薛西斯在岸边黄金座椅上目睹自家舰队溃败。一年后，前 479 年普拉提亚决战，波斯统帅马尔多尼奥斯阵亡，入侵军被逐出希腊。',
