          '胜利立刻变成体系。前 478 年，雅典牵头组建提洛同盟，二百多个城邦纳贡结盟、共防波斯；同盟金库后来迁入雅典卫城，防卫费变成帝国贡金。雅典借战时威望推行民主改革、大兴土木——帕特农神庙就是用同盟的贡金与胜利的自信盖起来的。',
          '希波战争还决定了历史学的诞生：希罗多德写《历史》，就是为了「使希腊人与波斯人的功业不致湮没」——他给出的叙事框架，自由城邦对抗专制帝国——成为西方两千年自我想象的母本，无论史实多么复杂，这个二元叙事从未退场。',
          '而对波斯，失败并未伤筋动骨，帝国转向金钱外交，资助斯巴达打雅典。真正被这场胜利改变的，是胜利者自己：雅典霸权膨胀，斯巴达恐惧滋长——第一次胜利埋下了第二次自相残杀的种子。希波战争证明了小国可以战胜帝国，也证明了战胜帝国的联盟未必有第二次蜜月。',
