          '戏剧性的尾声来自庞培：他刚结束西班牙战事回师，恰好截住了最后一股五千人的突围残部，尽数歼灭。他写信给元老院自夸：「克拉苏砍倒了草，我拔掉了战争的根。」——顺手把平叛的头功抢走一半。两人随后共同出任执政官，都在踩着这场起义的政治台阶。',
