          '会议的最初倡议来自锡兰总理科伦坡会议的五国：印度尼赫鲁、印尼苏加诺、缅甸吴努、锡兰班达拉奈克与巴基斯坦，加上埃及纳赛尔与埃塞俄比亚，共同发起邀请。邀请名单刻意排除了殖民宗主与两大阵营的核心，29 个受邀国全部接受。',
