          '对中国，万隆是走向世界舞台的起点：从「求同存异」到和平共处五项原则，这些建立在万隆之上的话语至今仍是中国外交的基本词库。2015 年万隆会议六十周年，多国首脑重访这座山城——六十年过去，那二十九把椅子上坐着的国家，已经变成一百多个想自己书写规则的国家的先行者。',
