          '交换并非自动两利：谁得到什么、谁失去什么，取决于航线的方向与武器的差距。克罗斯比晚年提醒读者，大交换的结果不是物种更丰富，而是「基因池更贫瘠」——全球生态被拉平成少数几种作物与牲畜的世界。',
