          '对国王，7 月 14 日的实质是失去巴黎：路易十六拒绝流亡，承认三色徽章，此后他的每一次摇摆都在验证一个事实——旧制度的合法性已经交出去了。三年后君主制本身被废除；路易十六直到上断头台前，大概才真正读懂那个「无事」的荒诞。',
