          '瘟疫到来时，查士丁尼一世正站在事业的顶点。这位皇帝的日程表写满「恢复罗马」：533 年大将贝利撒留攻灭北非汪达尔王国，536 年光复罗马城，意大利哥特战争节节推进——分裂百年的西部有望重新归于一统。537 年，新落成的圣索菲亚大教堂穹顶落成，据载皇帝走进大殿感叹：「所罗门，我胜过了你。」',
          '帝国的另一面同样扎眼：连年战争与宏大兴建把财政榨到极限，税吏特里波尼乌斯的苛捐在都城激起 532 年尼卡暴动，三万人死于镇压——皇后狄奥多拉那句「紫袍是最美的裹尸布」稳住了帝位。这是一个高速运转、内部紧绷的帝国。',
          '生态背景可能给了病毒推手：536 年前后，全球性的火山喷发让阳光黯淡、夏季消失，农作物连年歉收，啮齿动物与人类都在挨饿。饥荒、鼠群、密集的港口与粮船——瘟疫的全部乘务员，已经登船。',
