          '军事后果立竿见影。贝利撒留的远征军因疫减员，意大利的哥特战争从速决战拖成十八年消耗战；帝国再无余力经营西部，568 年伦巴第人趁虚涌入意大利，占去半壁——查士丁尼收复的西部，大半在瘟疫与疲惫中流失。他 565 年去世时，带着一个统一梦已碎的帝国。',
          '经济的伤口更深：埃及粮仓的税入锐减，劳动力价格飞涨，城市人口萎缩。帝国从此由攻势转入守势——此后史家公认，六至七世纪之交拜占庭与波斯的百年互耗，加上瘟疫对双方肌体的掏空，为随后阿拉伯势力的崛起清空了棋盘。',
