          '它改写了帝国的命运曲线，也参与改写了世界的走向：地中海东部人口长期低迷、城市收缩，为七世纪伊斯兰势力的快速扩张提供了脆弱的地缘真空——这一因果链在学界虽有争论，但方向已成共识。一个微生物在人类没有察觉的时刻，重排了此后千年的文明格局。',
          '查士丁尼大瘟疫留给后世的，还有一份方法论遗产：它是人类第一次拥有一位记录详尽的瘟疫史家——普罗柯比对症状、传播、死亡处理的全景描写，成为流行病学的远古教材。一千四百年后人类面对新冠时重读它，会发现一切都在：抢购、封城、谣言、尸体处理的窘迫，以及穿越瘟疫仍要发动的战争。文明进步的是科技，未变的考题，是从不缺席。',
