          '政治代价同样具体：卡梅伦与梅两任首相黯然下台，工党的「红墙」选区在 2019 年集体倒向保守党又在此后回摆；苏格兰首席大臣以「实质变化」为由再度推动独立公投议程——联合王国本身的裂痕，比与欧盟的裂痕更难缝合。留在平民记忆里的，则是无数家庭在饭桌上第一次为选票翻脸。',
