          '更深远的影响在全球：2016 年的英国公投与同年年底的美国大选，被并视为民粹主义的分水岭年份。脱欧派当初的承诺清单——更少的移民、更多的钱、更快的贸易协议——兑现程度至今争议不断；而「拿回控制权」这句三个词的口号，已被写进世界各地运动的口号手册。主权的确拿回来了，至于拿回来做什么，英国仍在作答。',
