          '日本的作战计划（MI 作战）庞大而复杂：分兵阿留申佯攻、主力攻占中途岛、潜艇先期警戒、舰队埋伏待机——把胜利押在「美军不知道」上。但美军知道。1942 年春，海军的密码破译团队（战斗情报组）逐步破解了 JN-25 通信密码的钥匙，罗奇福特小组从堆积如山的电文里读出了「AF」——下一个目标。',
          '为验证 AF 就是中途岛，美军让中途岛守军用明码发了一份「淡水设备故障」的假电报；两天后，日方电文里出现了「AF 缺淡水」的情报。钓饵咬钩。尼米兹把仅有的三艘航母（企业、约克城、大黄蜂）埋伏在中途岛东北——约克城刚在珊瑚海重创，抢修七十二小时就出港，船坞里还留着焊花味。',
