          '下午，「飞龙」号还击重创「约克城」，但傍晚被美军舰载机找到，再次起火。山本的主力战列舰远在三百海里外，一夜权衡后下令撤退——战列舰对决的旧时代设想，被航母作战的现实埋葬。四艘日本主力航母沉没，损失二百四十八架飞机与大批不可再生的精锐飞行员；美军损失约克城号与一百五十架飞机。',
