        heading: '代价：飞行员、情报与判断',
        paragraphs: [
          '日本损失的真正核心是人：训练了两年的舰载机精英飞行员与机械师随舰沉没，战前那种「一年只练百人」的精英培养体系再也无法补齐。此后日军的每一次作战，都在消耗一支补不上的队伍——中途岛之后，日本海军的战略姿态从进攻转为守势，这是开战以来的第一次。',
          '美军也付出了代价：鱼雷机中队的牺牲率近乎百分之百，约克城号沉没，一百五十名飞行员阵亡或失踪。但美国的工业机器随即将损失变成数字游戏：此后两年，美国下水了十七艘埃塞克斯级航母，日本只添了两艘中型舰。中途岛的胜负，一半在海上，一半在船坞。',
          '战争结束后的反思集中于日方的「胜利病」：珍珠港与此前半年连战连捷造成的判断力退化，分散兵力、侦察不力、换弹决策、迷信战列舰决战——山本的司令部被自己的神话绊倒。战役史家戈登·普兰奇的《中途岛奇迹》成为战史研究的标准读物。',
        ],
