          '另一个后果是依赖：种子、化肥、柴油构成的新农业体系，把农民嵌进全球市场——粮价一涨，播种成本先涨。1970 年代的石油危机让化肥价格飙升，许多发展中国家刚刚自给的粮食体系再度动摇。绿色革命解决了饥荒的近忧，种下了农业依赖的远虑。',
