          '铁托时代的南斯拉夫是冷战里的特例：不结盟运动的领袖，西方与苏联都拉拢，护照通行世界，经济在 1960—70 年代高速增长。但国家靠三根柱子撑着：铁托的威望、经济的繁荣、对民族主义的强力压制。1980 年铁托死后，第一根柱子倒了；1980 年代的通胀与外债，第二根也倒了。',
