      '1944 年 6 月 6 日，代号「D-Day」。凌晨，两千四百架轰炸机先炸碎德军的滩头神经；六点半，五千艘舰船把十五万六千名盟军士兵送上诺曼底的五处海滩——犹他、奥马哈、黄金、朱诺、宝剑。他们要从一个被希特勒经营四年的「大西洋壁垒」上撕开一道口子。到日落时，盟军伤亡约一万人，滩头阵地立住了。艾森豪威尔当晚的公报只有一句：这一仗，只是开场。',
