          '对亲历者来说，这一天是「最长的一天」（罗纳德导演的战争片名即取自隆美尔参谋长的话）：奥马哈滩头的美军士兵趴在水线时，很多人一辈子没能再睡一个安稳觉。诺曼底的美军公墓里，九千三百八十七块白色十字朝着海的方向——他们没能看到日落，但日落属于他们。登陆成功之后的代价清单同样惊人：诺曼底战役到 7 月底，盟军伤亡超过二十万；卡昂古城在轰炸中变成废墟，两万法国平民死于这场「解放的炮火」——法国历史学家至今仍在争论如何书写这段「被解放者的创伤」。',
