          '而在巴黎，纪念的核心始终是拉雪兹公墓东北角的那面墙：1880 年公社赦免后，幸存者每年五月末到墙前献花；1971 年百年纪念，巴黎市民在墙前立起纪念牌。无论意识形态如何变迁，「公社社员墙」前的鲜花，一个多世纪以来从未断过。',
