          '1773 年的《茶叶法》反而成了压垮骆驼的最后一根稻草：为拯救濒临破产的东印度公司，议会允许它绕过中间商直接向北美卖茶——加上关税后的「便宜茶」。这招非常毒辣：如果殖民者为了便宜把茶喝了，就等于默认了议会的征税权。波士顿的回答是把茶倒掉——拒绝受贿式的便宜，保卫原则。费城与纽约的茶船同样被逼回；唯有波士顿走得更远：把「财产」直接销毁了。',
