          '倒茶的人当时并不想独立：他们自称是英国人的合法权利的捍卫者，引用的正是英国宪法与辉格党的反抗暴政论。革命的激进性是随后十八个月里一步步长出来的——当英国用军队回应抗议，反抗的逻辑就从「反对税」滑向「反对王」。今天美国人把茶党视为自由的起源仪式，甚至 2009 年的保守派运动也自名「茶党」——一船茶叶的典故，成了这个国家政治语言里的原点。',
