          '彼得在庆功宴上举杯，据说敬了被俘的瑞典军官一杯——为他的「老师们」干杯：是纳尔瓦的惨败教会了俄国打仗。这句话的史实细节存疑，但它精准概括了彼得式现代化的逻辑：把屈辱当学费。圣彼得堡的雕像与波尔塔瓦的战场纪念物，至今分立两国，各讲各的版本。',
          '马泽帕与哥萨克的命运是另一条记忆线：乌克兰的民族叙事把马泽帕尊为反抗帝国的前驱，俄国的叙事则给他钉上叛徒的标签——同一条第聂伯河，立着两种纪念碑。波尔塔瓦因此不只是军事史，也是此后三百年东欧身份政治的一个起点。',
