      '1648 年 10 月，德意志西部的两座小城明斯特与奥斯纳布吕克，挤满了欧洲几乎全部强国的使节。他们在两份和约上签字，为一场打了三十年的宗教战争收尾——战争把德意志变成坟场，把欧洲的外交官们逼进了同一间会议厅。没有人意识到，这两份文书同时颁发了一张出生证：以主权国家为单位的近代国际体系，从此诞生。',
