          '「威斯特伐利亚」由此成为国际关系学的元概念：学者用它命名主权体系，也用它批评体系——对内压迫、对外战争的主权国家，恰恰是被这套原则保护的。二十世纪末以来，「后威斯特伐利亚」成为讨论全球化、人权干预与欧盟超国家的常用开场白。',
