          '1936 年 2 月，左翼人民阵线险胜大选，土地占夺与政治暴力升级；7 月 17 日，西属摩洛哥驻军起事，本土驻军次第响应。叛军迅速控制西部与南部，却在马德里、巴塞罗那、瓦伦西亚等工业与大城市碰壁——西班牙被拦腰切成两半。',
